from pathlib import Path
import json,html,shutil
from PIL import Image,ImageDraw,ImageFont
R=Path('/Users/james/Developer/Hackathon/Design/Presentation/Finn-Keynote-2026-10-16');K=R/'keynote';S=json.loads((K/'five-minute-scenes.json').read_text())
for k in ['index.html','speaker-notes.html']:
 a=R/'production/archive-v3';a.mkdir(exist_ok=True)
 if not (a/k).exists():shutil.copy2(R/k,a/k)
css='body{margin:0;background:#000;color:#fff;font-family:-apple-system,BlinkMacSystemFont,sans-serif}main{position:fixed;inset:0;display:grid;place-items:center}video{width:100%;height:100%;object-fit:contain}nav{position:fixed;bottom:16px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:8px;background:#222e;border-radius:18px;padding:10px;opacity:0;transition:opacity .2s}body:hover nav,nav:focus-within{opacity:1}button,a{font:inherit;color:inherit}button{border:0;border-radius:8px;padding:10px;background:#ffffff20;cursor:pointer}#notes{display:none;position:fixed;right:20px;bottom:90px;background:#202024f5;border-radius:20px;padding:30px;max-width:580px;line-height:1.5}#notes.open{display:block}#start{position:fixed;inset:0;display:grid;place-items:center;background:#0008}#start button{font-size:28px;padding:20px 35px}#count{white-space:nowrap}#notes small{color:#aaa}'
js='''const scenes=SCENES,v=document.querySelector('video'),count=document.querySelector('#count'),notes=document.querySelector('#notes');let i=0,auto=true;function show(n,play=true){i=Math.max(0,Math.min(scenes.length-1,n));let s=scenes[i];v.src=i===0?'videos/finn-opening-film.mp4':`keynote/media/${String(i+1).padStart(2,'0')}.mp4`;v.poster=`keynote/preview/${String(i+1).padStart(2,'0')}.png`;count.textContent=`${i+1} / 10`;notes.innerHTML=`<h2>${s.title}</h2><p>${s.notes.split('Sources:')[0].split('Source:')[0]}</p><small>${s.seconds}s · 5:00 total</small>`;location.hash=i+1;if(play)v.play().catch(()=>{});}v.onended=()=>{if(auto&&i<9)show(i+1)};document.querySelector('#go').onclick=()=>{document.querySelector('#start').style.display='none';show(0)};document.querySelector('#prev').onclick=()=>show(i-1);document.querySelector('#next').onclick=()=>show(i+1);document.querySelector('#pause').onclick=()=>v.paused?v.play():v.pause();document.querySelector('#replay').onclick=()=>show(i);document.querySelector('#note').onclick=()=>notes.classList.toggle('open');document.querySelector('#auto').onclick=e=>{auto=!auto;e.target.textContent=auto?'Auto advance on':'Auto advance off'};document.querySelector('#full').onclick=()=>document.documentElement.requestFullscreen();addEventListener('keydown',e=>{if(e.key==='ArrowRight')show(i+1);if(e.key==='ArrowLeft')show(i-1);if(e.key===' '){e.preventDefault();v.paused?v.play():v.pause()}if(e.key.toLowerCase()==='n')notes.classList.toggle('open')});show(Math.max(0,Number(location.hash.slice(1)||1)-1),false);'''.replace('SCENES',json.dumps(S,ensure_ascii=False))
(R/'index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Finn · Five minutes</title><style>'+css+'</style><main><video playsinline preload="metadata"></video></main><nav><button id="prev">←</button><span id="count"></span><button id="next">→</button><button id="pause">Play / pause</button><button id="replay">Replay</button><button id="note">Notes</button><button id="auto">Auto advance on</button><button id="full">Full screen</button><a href="speaker-notes.html">Script</a></nav><aside id="notes"></aside><div id="start"><button id="go">Play five-minute presentation</button></div><script>'+js+'</script></html>')
style='body{font:20px/1.6 -apple-system,BlinkMacSystemFont,sans-serif;background:#f5f5f7;color:#1d1d1f;margin:0}main{max-width:1000px;margin:auto;padding:60px 30px}h1{font-size:64px;line-height:1}section{margin:50px 0;border-top:1px solid #ddd;padding-top:20px}img{width:100%;border-radius:16px}.time{color:#c71a68}a{color:#c71a68}small{color:#6e6e73}'
body='<h1>Finn.<br>Five minutes.</h1><p>10 scenes · one-minute opening film · four-minute spoken presentation</p><p><a href="index.html">Rehearse</a> · <a href="keynote/output/Finn-Five-Minutes.key">Keynote</a> · <a href="keynote/output/Finn-Five-Minutes-Playback.mp4">Five-minute playback backup</a></p>'
def ts(t):return f'{t//60}:{t%60:02}'
for s in S:body+=f'<section><p class="time">{s["number"]:02} · {ts(s["start_seconds"])}–{ts(s["start_seconds"]+s["seconds"])}</p><h2>{html.escape(s["title"])}</h2><img src="keynote/preview/{s["number"]:02}.png"><p>{html.escape(s["notes"]).replace(chr(10),"<br>")}</p></section>'
body+='<section><h2>Presentation notes</h2><p>Begin with the film. Total timing is five minutes, including one minute of film and 536 words of speaker notes. Pause and advance manually if rehearsal needs more time. Keynote’s embedded movies preserve choreography, typography, sound and device footage; the rendered motion is not individually editable as native Keynote builds.</p><p>Assets: official Apple bezels, SF Pro, Foundation Models icon and Fitness+ imagery, plus Finn’s own app artwork and UI. Previously generated human film plates remain. The form cue is scripted; matching Vision landmarks come from the generated footage. Do not describe the film as evidence of real-world detection accuracy. Camera form-coaching competitors exist; the talk does not claim market exclusivity.</p></section>'
(R/'speaker-notes.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><title>Finn · Five-minute script</title><style>'+style+'</style><main>'+body+'</main></html>')
im=Image.new('RGB',(1280,1800),'#222')
for i in range(10):im.paste(Image.open(K/f'preview/{i+1:02}.png').resize((640,360)),(i%2*640,i//2*360))
im.save(K/'preview/contact-sheet.jpg',quality=92)
for source in ['finn_five_min.py','finn_scene_layers.cjs','finn_render_keynote.py','finn_embed_media.py','finn_keynote_handoff.py','finn_export_launch.swift']:shutil.copy2('/tmp/'+source,R/'production/source'/source)
print('Five-minute rehearsal and presenter script ready')
